from typing import List

class Solution:
    def getStrongest(self, arr: List[int], k: int) -> List[int]:
        arr.sort()
        m = arr[(len(arr) - 1) // 2]
        left, right = 0, len(arr) - 1
        result = []
        while len(result) < k:
            if m - arr[left] > arr[right] - m:
                result.append(arr[left]); left += 1
            else:
                result.append(arr[right]); right -= 1
        return result

