import java.io.*;
import java.util.*;
class Solution {
    public int[] getStrongest(int[] arr, int k) {
        Arrays.sort(arr);
        int m = arr[(arr.length - 1) / 2];
        int left = 0, right = arr.length - 1;
        int[] res = new int[k];
        for (int i = 0; i < k; i++) {
            if (m - arr[left] > arr[right] - m) res[i] = arr[left++];
            else res[i] = arr[right--];
        }
        return res;
    }
}

