function getStrongest(arr, k) {
  arr.sort((a, b) => a - b);
  const m = arr[Math.floor((arr.length - 1) / 2)];
  let left = 0, right = arr.length - 1;
  const result = [];
  while (result.length < k) {
    if (m - arr[left] > arr[right] - m) result.push(arr[left++]);
    else result.push(arr[right--]);
  }
  return result;
}

